    p0=[rng.normal(),rng.uniform(0.2,3),rng.normal(),rng.normal(),rng.uniform(-1,3),rng.normal(),rng.normal(),rng.uniform(-1,3),rng.normal()]
    try:
        f=least_squares(lambda p: model(p)-s, p0, max_nfev=1000)
